-- Size: Transaction Time
cboe_bzxoptions_binaryorderentry_boe_v2_11_115.transaction_time.size = 8

-- Display: Transaction Time
cboe_bzxoptions_binaryorderentry_boe_v2_11_115.transaction_time.display = function(value)
  -- Parse unix nanosecond timestamp
  local seconds = (value / UInt64(1000000000)):tonumber()
  local nanoseconds = (value % UInt64(1000000000)):tonumber()

  return "Transaction Time: "..os.date("%Y-%m-%d %H:%M:%S.", seconds)..string.format("%09d", nanoseconds)
end

