-- New Complex Instrument Bitfield 1
cboe_bzxoptions_binaryorderentry_boe_v2_11_115.new_complex_instrument_bitfield_1 = {}

-- Size: New Complex Instrument Bitfield 1
cboe_bzxoptions_binaryorderentry_boe_v2_11_115.new_complex_instrument_bitfield_1.size = 1

-- Display: New Complex Instrument Bitfield 1
cboe_bzxoptions_binaryorderentry_boe_v2_11_115.new_complex_instrument_bitfield_1.display = function(range, value, packet, parent)
  local flags = {}

  -- Is New Complex Instrument Bitfield 1 Leg Cfi Code flag set?
  if bit.band(value, 0x01) ~= 0 then
    flags[#flags + 1] = "New Complex Instrument Bitfield 1 Leg Cfi Code"
  end
  -- Is New Complex Instrument Bitfield 1 Leg Maturity Date flag set?
  if bit.band(value, 0x02) ~= 0 then
    flags[#flags + 1] = "New Complex Instrument Bitfield 1 Leg Maturity Date"
  end
  -- Is New Complex Instrument Bitfield 1 Leg Strike Price flag set?
  if bit.band(value, 0x04) ~= 0 then
    flags[#flags + 1] = "New Complex Instrument Bitfield 1 Leg Strike Price"
  end
  -- Is New Complex Instrument Bitfield 1 Clearing Firm flag set?
  if bit.band(value, 0x08) ~= 0 then
    flags[#flags + 1] = "New Complex Instrument Bitfield 1 Clearing Firm"
  end
  -- Is New Complex Instrument Bitfield 1 Reserved 16 flag set?
  if bit.band(value, 0x10) ~= 0 then
    flags[#flags + 1] = "New Complex Instrument Bitfield 1 Reserved 16"
  end
  -- Is New Complex Instrument Bitfield 1 Reserved 32 flag set?
  if bit.band(value, 0x20) ~= 0 then
    flags[#flags + 1] = "New Complex Instrument Bitfield 1 Reserved 32"
  end
  -- Is New Complex Instrument Bitfield 1 Reserved 64 flag set?
  if bit.band(value, 0x40) ~= 0 then
    flags[#flags + 1] = "New Complex Instrument Bitfield 1 Reserved 64"
  end
  -- Is New Complex Instrument Bitfield 1 Reserved 128 flag set?
  if bit.band(value, 0x80) ~= 0 then
    flags[#flags + 1] = "New Complex Instrument Bitfield 1 Reserved 128"
  end

  return table.concat(flags, "|")
end

