  local flags = {}

  -- Is New Complex Order Bitfield 9 Reserved 1 flag set?
  if bit.band(value, 0x01) ~= 0 then
    flags[#flags + 1] = "New Complex Order Bitfield 9 Reserved 1"
  end
  -- Is New Complex Order Bitfield 9 Cross Initiator flag set?
  if bit.band(value, 0x02) ~= 0 then
    flags[#flags + 1] = "New Complex Order Bitfield 9 Cross Initiator"
  end
